import java.util.*;

class Solution {
    public int loopStart(int[] charge, int[] drain) {
        int n = charge.length;
        long[] p = new long[n + 1];                     // p[k] = net balance after points 0..k-1
        for (int i = 0; i < n; i++) p[i + 1] = p[i] + charge[i] - drain[i];
        long total = p[n];
        if (total < 0) return -1;
        long[] sufMin = new long[n + 1];                // sufMin[j] = min p[j+1..n]
        sufMin[n] = Long.MAX_VALUE;
        for (int j = n - 1; j >= 0; j--) sufMin[j] = Math.min(sufMin[j + 1], p[j + 1]);
        long preMin = Long.MAX_VALUE;                   // min p[1..j], used after wrapping
        for (int j = 0; j < n; j++) {
            if (j > 0) preMin = Math.min(preMin, p[j]);
            boolean okBefore = p[j] <= sufMin[j];                  // stretch j..n-1
            boolean okAfter = j == 0 || p[j] <= total + preMin;    // wrapped stretch 0..j-1
            if (okBefore && okAfter) return j;
        }
        return -1;
    }
}

