class Solution:
    def loopStart(self, charge: List[int], drain: List[int]) -> int:
        n = len(charge)
        if sum(charge) < sum(drain): return -1
        # every start j where all prefix balances from j are >= 0: compute via prefix sums
        d = [charge[i % n] - drain[i % n] for i in range(2 * n)]
        p = [0] * (2 * n + 1)
        for i in range(2 * n): p[i + 1] = p[i] + d[i]
        # start j valid iff min(p[j+1..j+n]) - p[j] >= 0; sliding window min
        dq = deque()
        for k in range(1, n + 1):
            while dq and p[dq[-1]] >= p[k]: dq.pop()
            dq.append(k)
        for j in range(n):
            if p[dq[0]] - p[j] >= 0: return j
            k = j + n + 1
            while dq and p[dq[-1]] >= p[k]: dq.pop()
            dq.append(k)
            while dq[0] <= j + 1: dq.popleft()
        return -1

