function loopStart(charge, drain) {
  const n = charge.length;
  let tot = 0; for (let i = 0; i < n; i++) tot += charge[i] - drain[i];
  if (tot < 0) return -1;
  for (let j = 0; j < n; j++) {
    let b = 0, ok = true;
    for (let k = 0; k < n; k++) { const i = (j + k) % n; b += charge[i] - drain[i]; if (b < 0) { ok = false; break; } }
    if (ok) return j;
  }
  return -1;
}
